SELECT id, store_name, opened_date, sqft, AVG(sqft) OVER w_running AS sqft_avg_3_prior, AVG(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS sqft_avg_2_prior, SUM(sqft) OVER w_part AS cumulative_sqft FROM stores WHERE sqft BETWEEN 5719 AND 9728 WINDOW w_running AS (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING), w_part AS (ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
